 "content": "def transform(grid):
    """Reconstruct the recursive tiling hidden by the 3-colored band."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find a full-width or full-height 3-colored band; its thickness is one tile.
    band_rows = [r for r in range(h) if all(v == 3 for v in g[r])]
    band_cols = [c for c in range(w) if all(g[r][c] == 3 for r in range(h))]
    if band_rows:
        axis = 'row'
        band = band_rows
        n = len(band)
        N = (h + 1) // (n + 1)
        missing = band[0] // (n + 1)
    else:
        axis = 'col'
        band = band_cols
        n = len(band)
        N = (w + 1) // (n + 1)
        missing = band[0] // (n + 1)

    starts = [i * (n + 1) for i in range(N)]
    def get_tile(br, bc):
        return [g[starts[br] + i][starts[bc]:starts[bc] + n] for i in range(n)]
    def has_pattern(tile):
        return any(v in (2, 8) for row in tile for v in row)

    # The tile whose 2-mask matches the visible macro-layout is its recursive rule.
    candidates = []
    for br in range(N):
        for bc in range(N):
            if axis == 'row' and br == missing:
                continue
            if axis == 'col' and bc == missing:
                continue
            tile = get_tile(br, bc)
            if has_pattern(tile):
                mismatch = 0
                for rr in range(N):
                    for cc in range(N):
                        hidden = (axis == 'row' and rr == missing) or (axis == 'col' and cc == missing)
                        if hidden:
                            continue
                        occ = has_pattern(get_tile(rr, cc))
                        expected = tile[rr][cc] in (2, 8)
                        mismatch += (occ != expected)
                candidates.append((mismatch, -sum(v in (2, 8) for row in tile for v in row), tile))
    template = min(candidates, key=lambda x: (x[0], x[1]))[2]

    # The band hides a macro row/column. Populate its patterned cells with the template.
    for rr in range(N):
        for cc in range(N):
            hidden = (axis == 'row' and rr == missing) or (axis == 'col' and cc == missing)
            if not hidden:
                continue
            if template[rr][cc] in (2, 8):
                for i in range(n):
                    for j in range(n):
                        g[starts[rr] + i][starts[cc] + j] = 2 if template[i][j] in (2, 8) else 0
            else:
                for i in range(n):
                    for j in range(n):
                        g[starts[rr] + i][starts[cc] + j] = 0

    # Highlight within each tile the template cell corresponding to its macro position.
    for rr in range(N):
        for cc in range(N):
            tile_r, tile_c = starts[rr], starts[cc]
            if g[tile_r + rr][tile_c + cc] == 2:
                g[tile_r + rr][tile_c + cc] = 8
    return g
