def transform(grid):
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])

    # Find the solid 3 band that masks one tile row or column.
    full_rows = [r for r in range(h) if all(v == 3 for v in g[r])]
    full_cols = [c for c in range(w) if all(g[r][c] == 3 for r in range(h))]
    if full_rows:
        axis, band_start, size, dim = "row", full_rows[0], len(full_rows), h
    else:
        axis, band_start, size, dim = "col", full_cols[0], len(full_cols), w

    stride = size + 1
    count = (dim + 1) // stride
    missing = band_start // stride
    starts = [i * stride for i in range(count)]

    def get_tile(br, bc):
        return tuple(tuple(g[starts[br] + i][starts[bc] + j]
                           for j in range(size)) for i in range(size))

    def is_hidden(br, bc):
        return (axis == "row" and br == missing) or (axis == "col" and bc == missing)

    # Select the common tile from the nearest visible parallel tile row/column.
    candidates = []
    for d in range(1, count + 1):
        near = missing + d if missing + d < count else missing - d
        if not 0 <= near < count:
            continue
        line_tiles = []
        for k in range(count):
            t = get_tile(near, k) if axis == "row" else get_tile(k, near)
            if any(v == 2 for row in t for v in row):
                line_tiles.append(t)
        if line_tiles:
            candidates = line_tiles
            break
    if not candidates:
        candidates = [get_tile(br, bc) for br in range(count) for bc in range(count)
                      if not is_hidden(br, bc)
                      and any(v == 2 for row in get_tile(br, bc) for v in row)]
    motif = Counter(candidates).most_common(1)[0][0]

    # Replace the mask with zeros, then reconstruct its tiles from the motif's
    # own pixel at the corresponding macro-grid coordinate.
    if axis == "row":
        for r in range(band_start, band_start + size):
            for c in range(w):
                g[r][c] = 0
    else:
        for r in range(h):
            for c in range(band_start, band_start + size):
                g[r][c] = 0

    for br in range(count):
        for bc in range(count):
            if is_hidden(br, bc) and motif[br][bc] == 2:
                for i in range(size):
                    for j in range(size):
                        g[starts[br] + i][starts[bc] + j] = motif[i][j]

    # Highlight the motif pixel at each tile's macro-grid coordinate.
    for br in range(count):
        for bc in range(count):
            r, c = starts[br] + br, starts[bc] + bc
            if g[r][c] == 2:
                g[r][c] = 8
    return g
